#include <Eigen/Dense>
#include <iostream>
#include <vector>
#include <cmath>
#include <iomanip>

using namespace Eigen;

// Global-ish state mimicking Fortran COMMON
struct State {
    double E = 200e9, nu = 0.3, GG;
    double HDETER;
    int NPVT = 0;
    double K[18][18]; // global 18x18 stiffness
};

// Invert 4x4 matrix, return determinant
static double invert4(const Matrix4d& H, Matrix4d& Hinv, int& ising) {
    double det = H.determinant();
    ising = 0;
    if (std::abs(det) < 1e-300) { ising = 2; return det; }
    Hinv = H.inverse();
    return det;
}

// SAXB: cross product R = R12 x R13
static void SAXB(const double* a, const double* b, double* r) {
    r[0] = a[1]*b[2] - a[2]*b[1];
    r[1] = a[2]*b[0] - a[0]*b[2];
    r[2] = a[0]*b[1] - a[1]*b[0];
}
static double SADOTB(const double* a, const double* b) {
    return a[0]*b[0]+a[1]*b[1]+a[2]*b[2];
}

// KTETRA: process one tetrahedron
// ecpt: 23-element array (1-based in Fortran -> 0-based here)
// iopt: option
// jtype: element type
// state: global state
// Kglobal: 18x18 global stiffness (for wedge, 6 nodes)
// nodeMap: mapping from tetra local node (0..3) to wedge node (0..5)
static void KTETRA(int iopt, int jtype, double* ecpt, State& st,
                   MatrixXd& Kglobal, const int* nodeMap) {
    // Build H matrix (4x4)
    Matrix4d H;
    H(0,0)=1.0; H(0,1)=ecpt[7]; H(0,2)=ecpt[8]; H(0,3)=ecpt[9];
    H(1,0)=1.0; H(1,1)=ecpt[11]; H(1,2)=ecpt[12]; H(1,3)=ecpt[13];
    H(2,0)=1.0; H(2,1)=ecpt[15]; H(2,2)=ecpt[16]; H(2,3)=ecpt[17];
    H(3,0)=1.0; H(3,1)=ecpt[19]; H(3,2)=ecpt[20]; H(3,3)=ecpt[21];

    Matrix4d Hinv;
    int ising;
    double hdeter = invert4(H, Hinv, ising);
    if (ising == 2) return;
    st.HDETER = std::abs(hdeter);

    // Material matrix G (6x6)
    Matrix<double,6,6> G = Matrix<double,6,6>::Zero();
    double E = st.E, nu = st.nu;
    double GG = E/(2.0*(1.0+nu));
    double temp1 = (1.0+nu)*(1.0-2.0*nu);
    double g1 = E*(1.0-nu)/temp1;
    double g2 = E*nu/temp1;
    G(0,0)=g1; G(1,1)=g1; G(2,2)=g1;
    G(0,1)=g2; G(0,2)=g2;
    G(1,0)=g2; G(1,2)=g2;
    G(2,0)=g2; G(2,1)=g2;
    G(3,3)=GG; G(4,4)=GG; G(5,5)=GG;

    // Build 4 C matrices (6x3 each) from Hinv
    // C(J+1)=Hinv(I+4) etc. In Fortran H is 1-based column-major.
    // H(I+4) with I=1..4 -> H(5),H(6),H(7),H(8) 1-based = Hinv(1,1),Hinv(2,1),Hinv(3,1),Hinv(4,1)
    // Actually H is stored column-major: H(1..4)=col1, H(5..8)=col2, H(9..12)=col3, H(13..16)=col4
    // H(I+4) = col2 row I = Hinv(I-1, 1) 0-based
    // H(I+8) = col3 row I = Hinv(I-1, 2)
    // H(I+12)= col4 row I = Hinv(I-1, 3)
    // C is 6x3 per tetra, stored as 18 values. C(J+1..J+18) with J=18*I-18.
    // C(J+1)=H(I+4), C(J+5)=H(I+8), C(J+9)=H(I+12), C(J+11)=H(I+12),
    // C(J+12)=H(I+8), C(J+13)=H(I+12), C(J+15)=H(I+4), C(J+16)=H(I+8), C(J+17)=H(I+4)
    // C is 6x3 column-major: C(1..6)=col1, C(7..12)=col2, C(13..18)=col3
