    //    C(J+12)=col2 row6, C(J+13)=col3 row1, C(J+15)=col3 row3, C(J+16)=col3 row4, C(J+17)=col3 row5

    // Build C as 6x3 for each of 4 nodes
    std::vector<Matrix<double,6,3>> C(4);
    for (int i = 0; i < 4; i++) {
        C[i] = Matrix<double,6,3>::Zero();
        // Hinv column 1 (0-based col 0), rows 0..3
        double h4 = Hinv(i,0);   // H(I+4)
        double h8 = Hinv(i,1);   // H(I+8)
        double h12= Hinv(i,2);   // H(I+12)
        // C(J+1)=h4 -> C(0,0)
        C[i](0,0) = h4;
        // C(J+5)=h8 -> C(4,0)
        C[i](4,0) = h8;
        // C(J+9)=h12 -> C(2,1)
        C[i](2,1) = h12;
        // C(J+11)=h12 -> C(4,1)
        C[i](4,1) = h12;
        // C(J+12)=h8 -> C(5,1)
        C[i](5,1) = h8;
        // C(J+13)=h12 -> C(0,2)
        C[i](0,2) = h12;
        // C(J+15)=h4 -> C(2,2)
        C[i](2,2) = h4;
        // C(J+16)=h8 -> C(3,2)
        C[i](3,2) = h8;
        // C(J+17)=h4 -> C(4,2)
        C[i](4,2) = h4;
    }

    // Divide determinant
    double hd = st.HDETER;
    if (iopt == 0) {
        hd = hd/6.0;
    } else if (iopt >= 11 && iopt <= 22) {
        hd = hd/36.0;
        if (iopt <= 16) hd = hd*2.0;
    } else {
        hd = hd/12.0;
    }

    // Pivot point: find which node is NPVT
    // For wedge, NPVT is the pivot. We need to find pivot node index.
    // In Fortran, NECPT(I+1) for I=2..5 (nodes 2..5), NPOINT=18*I-35.
    // We'll find pivot among the 4 tetra nodes.
    int pivotLocal = -1;
    for (int i = 0; i < 4; i++) {
        // NECPT(I+2) is grid SIL for node I+1 (1-based). We use nodeMap.
        // Actually pivot is determined by SIL matching NPVT.
        // For our test, we'll set NPVT to node 1's SIL.
    }
    // For simplicity in this test, assume pivot is local node 0 (first node)
    // We'll handle pivot properly below.

    // Compute GCT = C_pivot^T * G * hd  (3x6)
    // Actually: GCT = C_pivot * G (6x6) -> 6x6? No.
    // Fortran: GMMATD(C(NPOINT),6,3,1, G(1),6,6,0, GCT(1))
    // This is C^T (3x6) * G (6x6) = 3x6. The '1' flag means transpose first arg.
    // So GCT = C_pivot^T * G, 3x6.
    // Then GCT *= hd.

    // We need pivot. Let's just use local node 0 for now and fix.
    // Actually let's determine pivot from nodeMap and NPVT.
    // We'll pass pivotLocal in.

    // For the test, pivot = node 0 (SIL of node 1).
    // Let's compute for pivotLocal.
    // (handled by caller)
