    // ECPT(1)=EL ID, ECPT(2)=MAT ID, ECPT(3..8)=GRID SILs 1..6,
    // ECPT(9)=CSID1, ECPT(10..12)=X1,Y1,Z1, ECPT(13)=CSID2, ECPT(14..16)=X2,Y2,Z2, ...
    // From the table: ECPT(9)=CSID-1, ECPT(10)=X1, ECPT(11)=Y1, ECPT(12)=Z1,
    // ECPT(13)=CSID-2, ECPT(14)=X2, ECPT(15)=Y2, ECPT(16)=Z2, ...
    // ECPT(33)=ELTEMP

    // We'll build a 100-element ECPT array (0-based, so index 0..99)
    std::vector<double> ECPT(100, 0.0);
    // Use integer view for SILs
    // ECPT(1)=1 (el id), ECPT(2)=1 (mat id)
    ECPT[0] = 1.0; // el id
