        double hdeter = H.determinant();
        if (std::abs(hdeter) < 1e-300) continue;
        Matrix4d Hinv = H.inverse();
        hdeter = std::abs(hdeter);

        // Material G
        double E = 200e9, nu = 0.3;
        double GG = E/(2.0*(1.0+nu));
        double temp1 = (1.0+nu)*(1.0-2.0*nu);
        double g1 = E*(1.0-nu)/temp1;
        double g2 = E*nu/temp1;
        Matrix<double,6,6> G = Matrix<double,6,6>::Zero();
        G(0,0)=g1; G(1,1)=g1; G(2,2)=g1;
        G(0,1)=g2; G(0,2)=g2;
        G(1,0)=g2; G(1,2)=g2;
        G(2,0)=g2; G(2,1)=g2;
        G(3,3)=GG; G(4,4)=GG; G(5,5)=GG;

        // Build C matrices (6x3 each)
        std::vector<Matrix<double,6,3>> C(4);
        for (int i = 0; i < 4; i++) {
            C[i] = Matrix<double,6,3>::Zero();
            double h4 = Hinv(i,0);
            double h8 = Hinv(i,1);
            double h12= Hinv(i,2);
            C[i](0,0) = h4;
            C[i](4,0) = h8;
            C[i](2,1) = h12;
            C[i](4,1) = h12;
            C[i](5,1) = h8;
            C[i](0,2) = h12;
            C[i](2,2) = h4;
            C[i](3,2) = h8;
            C[i](4,2) = h4;
        }

        // Divide determinant
        double hd;
        int iopt = itet + 11; // IOPT = I + 10, I is 1-based itet
        // Actually IOPT = I + 10 where I is the loop index (1-based)
        iopt = (itet+1) + 10;
        if (iopt >= 11 && iopt <= 22) {
            hd = hdeter/36.0;
