            hd = hdeter/6.0;
        }

        // Find pivot local node
        int pivotLocal = -1;
        for (int i = 0; i < 4; i++) {
            if (nodeMap[i]+1 == NPVT) { pivotLocal = i; break; }
        }
        if (pivotLocal < 0) continue;

        // GCT = C_pivot^T * G * hd  (3x6)
        Matrix<double,3,6> GCT = C[pivotLocal].transpose() * G;
        GCT *= hd;

        // For each of 4 nodes, compute KIJ (3x3) and insert
        for (int i = 0; i < 4; i++) {
            Matrix3d KIJ = GCT * C[i]; // (3x6)*(6x3) = 3x3
            // Insert into global K at node nodeMap[i], node nodeMap[pivotLocal]
            int ni = nodeMap[i];
            int np = nodeMap[pivotLocal];
            for (int a = 0; a < 3; a++)
                for (int b = 0; b < 3; b++)
                    K(3*ni+a, 3*np+b) += KIJ(a,b);
        }
    }

    // Print as JSON
    std::cout << "{\"stiffness_matrix\":[";
    for (int i = 0; i < 18; i++) {
        std::cout << "[";
        for (int j = 0; j < 18; j++) {
            std::cout << std::scientific << std::setprecision(6) << K(i,j);
            if (j < 17) std::cout << ",";
        }
        std::cout << "]";
        if (i < 17) std::cout << ",";
    }
    std::cout << "]}" << std::endl;

    return 0;
}
